using System; using System.Drawing; using System.Drawing.Imaging;
public static class ButtonCrop { public static void Save(string source,string dest) { using(var im=new Bitmap(source)) { int[] cols=new int[im.Width],rows=new int[im.Height];for(int y=0;y<im.Height;y++)for(int x=0;x<im.Width;x++)if(im.GetPixel(x,y).A>40){cols[x]++;rows[y]++;}int l=0,r=im.Width-1,t=0,b=im.Height-1;while(l<r&&cols[l]<12)l++;while(r>l&&cols[r]<12)r--;while(t<b&&rows[t]<30)t++;while(b>t&&rows[b]<30)b--;l=Math.Max(0,l-18);r=Math.Min(im.Width-1,r+18);t=Math.Max(0,t-18);b=Math.Min(im.Height-1,b+18);using(var crop=im.Clone(new Rectangle(l,t,r-l+1,b-t+1),PixelFormat.Format32bppArgb)) {crop.Save(dest,ImageFormat.Png);} } } }
